mapper.select:
select *
from "conversation"
where sender_id = #{userId} or receiver_id = #{userId}

mapper.update:
update "conversation"
last_message_id = #{lastMessageId}, sender_last_message_id = #{senderLastMessageId}, receiver_last_message_id = #{receiverLastMessageId}, sender_unread_count = #{senderUnreadCount}, receiver_unread_count = #{receiverUnreadCount}, sender_deleted = #{senderDeleted}, receiver_deleted = #{receiverDeleted}, update_time = #{updateTime},
where id = #{id}
